    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                yesterday_bids.append(bid)

    # Determine base bid
    if hp <= 2 or no_water_days > 0:
        base_bid = DAILY_SALARY * 0.9
    else:
        if yesterday_bids:
            max_prev = max(yesterday_bids)
